// feedbackprivacy_test.go (step 3.8): the redaction vectors. Every case was
// generated by running the TS redactFeedbackText
// (packages/shared/src/feedbackPrivacy.ts) on the same inputs; the Go port
// must produce identical output. Privacy-sensitive by construction: no real
// endpoints or credentials, only synthetic markers.
package feedbackprivacy

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

type vector struct {
	Input      string `json:"input"`
	Diagnostic bool   `json:"diagnostic"`
	Output     string `json:"output"`
}

// vectorsJSON is embedded so the parity suite is self-contained; the same
// data also lives in go/testdata/vectors/feedback-privacy.json for the
// recorder parity scripts.
var vectorsJSON = `[
{"input":"{\"api_key\":\"sk-test-1234567890\"}","diagnostic":false,"output":"{\"api_key\":\"[REDACTED]\"}"},
{"input":"password=hunter2","diagnostic":false,"output":"password=[REDACTED]"},
{"input":"{\"nested\":{\"Authorization\":\"Bearer abc123\",\"safe\":\"keep\"}}","diagnostic":false,"output":"{\"nested\":{\"Authorization\":\"[REDACTED]\",\"safe\":\"keep\"}}"},
{"input":"Authorization: Bearer eyJhbGciOiJIUzI1NiJ9","diagnostic":false,"output":"Authorization: [REDACTED]"},
{"input":"-----BEGIN RSA PRIVATE KEY-----\nMIIEow\n-----END RSA PRIVATE KEY-----","diagnostic":false,"output":"[REDACTED]"},
{"input":"visit https://example.com/reset?token=abc123 now","diagnostic":false,"output":"visit https://example.com/[REDACTED] now"},
{"input":"file at /Users/alice/secret.txt and C:\\Users\\bob\\doc","diagnostic":false,"output":"file at [USER_PATH] and [USER_PATH]"},
{"input":"{\"messages\":[{\"role\":\"user\",\"content\":\"hello\"}]}","diagnostic":true,"output":"{\"messages\":\"[REDACTED]\"}"},
{"input":"email test@example.com kept in non-diagnostic","diagnostic":false,"output":"email test@example.com kept in non-diagnostic"},
{"input":"email test@example.com redacted in diagnostic","diagnostic":true,"output":"email [EMAIL] redacted in diagnostic"},
{"input":"log line {\"content\":\"inner\"} after","diagnostic":false,"output":"log line {\"content\":\"inner\"} after"},
{"input":"{\"password\":\"a\"} trailing","diagnostic":false,"output":"{\"password\":\"[REDACTED]\"} trailing"},
{"input":"plain text without secrets","diagnostic":false,"output":"plain text without secrets"},
{"input":"{\"headers\":{\"X-Api-Key\":\"sk-1\"}}","diagnostic":false,"output":"{\"headers\":{\"X-Api-Key\":\"[REDACTED]\"}}"},
{"input":"url https://hooks.slack.com/services/T00/B00/XXX","diagnostic":false,"output":"url https://hooks.slack.com/[REDACTED]"},
{"input":"{\"env\":{\"AWS_SECRET_ACCESS_KEY\":\"k\"}}","diagnostic":true,"output":"{\"env\":\"[REDACTED]\"}"},
{"input":"nested deep {\"a\":{\"b\":{\"c\":{\"d\":{\"e\":{\"secret\":\"x\"}}}}}}","diagnostic":false,"output":"nested deep {\"a\":{\"b\":{\"c\":{\"d\":{\"e\":{\"secret\":\"[REDACTED]\"}}}}}}"},
{"input":"cookie: sessionid=deadbeef","diagnostic":false,"output":"cookie: [REDACTED]"},
{"input":"{\"toolInput\":{\"command\":\"ls -la\"}}","diagnostic":true,"output":"{\"toolInput\":\"[REDACTED]\"}"},
{"input":"api_key = \"quoted value\"","diagnostic":false,"output":"api_key = [REDACTED]"},
{"input":"log: {\"content\":\"inner secret\"} after","diagnostic":true,"output":"log: {\"content\":\"[REDACTED]\"} after"},
{"input":"{\"content\":\"x\"}{\"safe\":\"y\"}","diagnostic":false,"output":"{\"content\":\"x\"}{\"safe\":\"y\"}"},
{"input":"line1\npassword=abc\nline3","diagnostic":false,"output":"line1\npassword=[REDACTED]\nline3"},
{"input":"{\"ok\":true} and api_key=zzz","diagnostic":false,"output":"{\"ok\":true} and api_key=[REDACTED]"},
{"input":"https://user:pass@example.com/path","diagnostic":false,"output":"https://example.com/[REDACTED]"},
{"input":"see https://cdn.example.com/downloads/signed/abc?X-Signature=q","diagnostic":false,"output":"see https://cdn.example.com/[REDACTED]"},
{"input":"{\"stdout\":\"no secrets\"}","diagnostic":true,"output":"{\"stdout\":\"[REDACTED]\"}"},
{"input":"{\"a\":{\"password\":\"x\"},\"b\":\"c\"}","diagnostic":false,"output":"{\"a\":{\"password\":\"[REDACTED]\"},\"b\":\"c\"}"},
{"input":"What about MY_TOKEN here?","diagnostic":false,"output":"What about MY_TOKEN here?"},
{"input":"request {\"headers\":{\"a\":\"b\"}} end","diagnostic":true,"output":"request {\"headers\":\"[REDACTED]\"} end"}
]`

func loadVectors(t *testing.T) []vector {
	t.Helper()
	var vectors []vector
	if err := json.Unmarshal([]byte(vectorsJSON), &vectors); err != nil {
		t.Fatal(err)
	}
	return vectors
}

// TestRedactionVectorsTSParity: byte-identical output against the TS
// implementation on the recorded corpus.
func TestRedactionVectorsTSParity(t *testing.T) {
	for i, v := range loadVectors(t) {
		if got := RedactFeedbackText(v.Input, v.Diagnostic); got != v.Output {
			t.Errorf("vector %d: input %q diagnostic=%v\n got  %q\n want %q", i, v.Input, v.Diagnostic, got, v.Output)
		}
	}
}

// TestNoSecretLeaks: after redaction, none of the known secret markers may
// survive anywhere in the output (defense-in-depth beyond exact matching).
func TestNoSecretLeaks(t *testing.T) {
	secrets := []string{"hunter2", "eyJhbGciOiJIUzI1NiJ9", "MIIEow", "sk-test-1234567890", "abc123", "deadbeef", "user:pass"}
	for _, v := range loadVectors(t) {
		output := RedactFeedbackText(v.Input, v.Diagnostic)
		for _, secret := range secrets {
			if len(secret) >= 6 && contains(output, secret) {
				t.Errorf("input %q leaked %q in %q", v.Input, secret, output)
			}
		}
	}
}

func contains(haystack, needle string) bool {
	return len(needle) > 0 && len(haystack) >= len(needle) && indexOf(haystack, needle) >= 0
}

func indexOf(haystack, needle string) int {
	for i := 0; i+len(needle) <= len(haystack); i++ {
		if haystack[i:i+len(needle)] == needle {
			return i
		}
	}
	return -1
}

// TestVectorsFileRoundTrip writes the corpus to the shared vectors location
// when absent, and validates a committed copy byte-for-byte when present —
// the recorder parity scripts consume the same file.
func TestVectorsFileRoundTrip(t *testing.T) {
	path := filepath.Join("..", "..", "testdata", "vectors", "feedback-privacy.json")
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return // the embedded corpus is authoritative in-tree for now
	}
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var fileVectors []vector
	if err := json.Unmarshal(data, &fileVectors); err != nil {
		t.Fatal(err)
	}
	embedded := loadVectors(t)
	if len(fileVectors) != len(embedded) {
		t.Fatalf("vector count drift: file %d embedded %d", len(fileVectors), len(embedded))
	}
	for i := range fileVectors {
		if fileVectors[i] != embedded[i] {
			t.Errorf("vector %d drifted from the embedded corpus", i)
		}
	}
}
